def get_financial_year_dates_range(year_range):
    # Split the year range (e.g., "2024-2025")
    year_start, year_end = year_range.split("-")
    # Financial year starts on April 1st and ends on March 31st
    start_date = f"{year_start}-04-01"
    end_date = f"{year_end}-03-31"
    # Convert to datetime objects
    start_date = datetime.datetime.strptime(start_date, "%Y-%m-%d")
    end_date = datetime.datetime.strptime(end_date, "%Y-%m-%d")
    return {"start_date": start_date, "end_date": end_date}


