def get_sap_data(arv_cum_do_numbers):
    sap_query = {"do_no": {"$in": arv_cum_do_numbers}}
    sap_pipeline = [
        {"$match": sap_query},
        {
            "$project": {
            "do_no": 1,
            "po_amount": {
                "$convert": {
                "input": {
                    "$replaceAll": {
                    "input": "$po_amount",
                    "find": ",",
                    "replacement": ""
                    }
                },
                "to": "double",
                "onError": None, 
                "onNull": None
                }
            }
            }
        }
    ]
    
    sap_results = list(SapRecords.objects().aggregate(sap_pipeline))
    
    sap_data = {item['do_no']: item['po_amount'] for item in sap_results}
    return sap_data

