@router.get("/fetch/gmrdata/dcdate/manual", tags=["Road Map"])
async def endpoint_to_fetch_gmrdata_dcdate(response: Response, currentPage: Optional[int] = None, perPage: Optional[int] = None, dc_date: Optional[str] = None, do_no: Optional[str] = None, challan_no: Optional[str] = None):
    try:
        result = {        
                "labels": [],
                "datasets": [],
                "total" : 0,
                "page_size": 15
        }
        page_no = 1
        page_len = result["page_size"]
        if currentPage:
            page_no = currentPage

        if perPage:
            page_len = perPage
            result["page_size"] = perPage
        
        offset = (page_no - 1) * page_len

        listData = []
        if do_no and dc_date and challan_no:
            dc_date = datetime.datetime.strptime(dc_date, "%d-%m-%Y").strftime("%-d-%-m-%Y")
            fetchGmrData = Gmrdata.objects(arv_cum_do_number__icontains=do_no, delivery_challan_date=dc_date, delivery_challan_number__icontains=challan_no).skip(offset).limit(page_len)
            result["total"]= len(Gmrdata.objects(arv_cum_do_number__icontains=do_no, delivery_challan_date=dc_date, delivery_challan_number__icontains=challan_no))
        elif do_no and dc_date:
            dc_date = datetime.datetime.strptime(dc_date, "%d-%m-%Y").strftime("%-d-%-m-%Y")
            fetchGmrData = Gmrdata.objects(arv_cum_do_number__icontains=do_no, delivery_challan_date=dc_date).skip(offset).limit(page_len)
            result["total"]= len(Gmrdata.objects(arv_cum_do_number__icontains=do_no, delivery_challan_date=dc_date))
        elif do_no and challan_no:
            fetchGmrData = Gmrdata.objects(arv_cum_do_number__icontains=do_no, delivery_challan_number__icontains=challan_no).skip(offset).limit(page_len)
            result["total"]= len(Gmrdata.objects(arv_cum_do_number__icontains=do_no, delivery_challan_number__icontains=challan_no))
        elif do_no:
            fetchGmrData = Gmrdata.objects(arv_cum_do_number__icontains=do_no).skip(offset).limit(page_len)
            result["total"]= len(Gmrdata.objects(arv_cum_do_number__icontains=do_no))
        elif dc_date:
            dc_date = datetime.datetime.strptime(dc_date, "%d-%m-%Y").strftime("%-d-%-m-%Y")
            fetchGmrData = Gmrdata.objects(delivery_challan_date=dc_date).skip(offset).limit(page_len)
            result["total"]= len(Gmrdata.objects(delivery_challan_date=dc_date))
        elif challan_no:
            fetchGmrData = Gmrdata.objects(delivery_challan_number__icontains=challan_no).skip(offset).limit(page_len)
            result["total"]= len(Gmrdata.objects(delivery_challan_number__icontains=challan_no))
        else:
            fetchGmrData = Gmrdata.objects().skip(offset).limit(page_len)
            result["total"]= len(Gmrdata.objects())
            
        if fetchGmrData:
            for single_data in fetchGmrData:
                dictData = single_data.payload()
                if dictData["Challan_Gross_Wt(MT)"]:
                    dictData["Challan_Gross_Wt(MT)"] = round(float(dictData["Challan_Gross_Wt(MT)"]), 2)
                if dictData["Challan_Tare_Wt(MT)"]:
                    dictData["Challan_Tare_Wt(MT)"] = round(float(dictData["Challan_Tare_Wt(MT)"]), 2)
                if dictData["Challan_Net_Wt(MT)"]:
                    dictData["Challan_Net_Wt(MT)"] = round(float(dictData["Challan_Net_Wt(MT)"]), 2)
                if dictData["GWEL_Gross_Wt(MT)"]:
                    dictData["GWEL_Gross_Wt(MT)"] = round(float(dictData["GWEL_Gross_Wt(MT)"]), 2)
                if dictData["GWEL_Tare_Wt(MT)"]:
                    dictData["GWEL_Tare_Wt(MT)"] = round(float(dictData["GWEL_Tare_Wt(MT)"]), 2)
                if dictData["GWEL_Net_Wt(MT)"]:
                    dictData["GWEL_Net_Wt(MT)"] = round(float(dictData["GWEL_Net_Wt(MT)"]), 2)
                if single_data.delivery_challan_date:
                    datesplit = single_data.delivery_challan_date.split("-")
                    date_form = f"{datesplit[0].zfill(2)}-{datesplit[1].zfill(2)}-{datesplit[2]}"
                    dictData.update({'DC_Date': date_form})
                listData.append(dictData)
            result["datasets"] = listData
            return result
        else:
            response.status_code = 404
            return {"details": "No data found"}
    except Exception as e:
        error_handler(e)


