        if mode=="road":
            per_data = '<table style="width: 100%; border-collapse: collapse; margin: 20px 0;">'
            per_data += '<thead><tr>'
            per_data += '<th style="border: 1px solid #ddd; padding: 8px; background-color: #003974; color: #fff;">Ship To Party</th>'
