def convert_xls_to_xlsx(path):
    try:
        folder_path=os.path.join(os.getcwd(),"sap_ftp","PO")
        if not path.rsplit('/', 1)[-1].endswith(('.XLS','.xls')):
            return {"error": "Uploaded file is not a xls"}
        file_name = path.rsplit('/', 1)[-1].split(".")[0]
        file_extension = path.split(".")[-1]
        with open(path, 'r') as f:
            data = f.readlines()
        rows = [line.strip().split('\t') for line in data]
        df = pd.DataFrame(rows)
        df.to_excel(f'{folder_path}/{file_name}.xlsx', index=False, header=False)
        return f"{folder_path}/{file_name}.xlsx", file_name
    except Exception as e:
        success = False
        error_handler(e)
    
@router.get("/convert/xls/xlsx", tags=["xls convert"])
def enpoint_to_convert_xls_to_xlsx(response: Response):
    try:
        folder_path=os.path.join(os.getcwd(),"sap_ftp","PO")
        files=os.listdir(folder_path)
        for filename in files:
            file_path = os.path.join(folder_path, filename)
            output_data, file_name = convert_xls_to_xlsx(file_path)
    except Exception as e:
        success = False
        error_handler(e)

