@router.post("/insert/avery/excel", tags=["Rail Data"])
async def endpoint_to_add_sap_excel_data(response: Response, sheet_name: str, file: UploadFile = File(...)):
    try:
        if file is None:
            return {"error": "No file Uploaded!"}
        contents = await file.read()
        if not contents:
            response.status_code = 400
            return {"error": "Uploaded file is empty!"}
        if file.filename.endswith(".xlsx"):
            # file saving start
            date = str(datetime.datetime.now().strftime("%d-%m-%Y"))
            target_directory = f"static_server/gmr_ai/{date}"
            os.umask(0)
            os.makedirs(target_directory, exist_ok=True, mode=0o777)
            file_extension = file.filename.split(".")[-1]
            file_name = f'coallab_sap_manual_{datetime.datetime.now().strftime("%Y-%m-%d:%H:%M")}.{file_extension}'
            full_path = os.path.join(os.getcwd(), target_directory, file_name)
            with open(full_path, "wb") as file_object:
                file_object.write(contents)
            # file saving end
            # xls = pd.ExcelFile(BytesIO(contents))
            # reading excel and skipping first two rows
            cleaned_data = pd.read_excel(BytesIO(contents), sheet_name=sheet_name, skiprows=2)
            cleaned_data.columns = [
                "S.no", "Source", "Rake No", "Unit/Month", "Source (repeat)", 
                "RR No", "RR Date", "Wagons", "RR Qty", "SECL Inv Qty", 
                "Rcvd Qty", "GRN Qty", "(Excess)/Shortage", "T/L%", "PO", 
                "Li NO", "Placement Date & Time", "Time", "Date", "Remarks"
            ]
            # dropping s.no as it doesn't have any use
            cleaned_data = cleaned_data.dropna(subset=["S.no"]).reset_index(drop=True)

            # Convert data into a list of dictionaries
            data_dicts = cleaned_data.to_dict(orient="records")

            for single_data_dict in data_dicts:
                try:
                    checkSingleRailData = RailData.objects.get(rr_no=single_data_dict.get("RR No"), total_secl_net_wt=single_data_dict.get("RR Qty"))
                    console_logger.debug("rail data there")
                except Exception as e:
                    console_logger.debug('rail data not there')
                    continue

        return {"detail": "success"}
    except KeyError as e:
        raise HTTPException(status_code=404, detail="Key Error")
    except Exception as e:
        response.status_code = 400
        error_handler(e)


@router.post("/annexure/rake/quota", tags=["Rcr Rake"])
async def endpoint_to_insert_ocr_rcr_rakequota_annexure(response: Response, pdf_upload: Optional[UploadFile] = File(None)):
    try:
        if pdf_upload is None:
            return {"error": "No file uploaded"}
        contents = await pdf_upload.read()
        # Check if the file is empty
        if not contents:
            return {"error": "Uploaded file is empty"}
        # Verify file format (PDF)
        if not pdf_upload.filename.endswith(('.pdf','.PDF')):
            response.status_code = 400
            return {"error": "Uploaded file is not a PDF"}
        file = str(datetime.datetime.now().strftime("%d-%m-%Y"))
        target_directory = f"static_server/gmr_ai/{file}"
        os.umask(0)
        os.makedirs(target_directory, exist_ok=True, mode=0o777)
        file_extension = pdf_upload.filename.split(".")[-1]
        file_name = f'pdf_{datetime.datetime.now().strftime("%Y-%m-%d:%H:%M")}.{file_extension}'
        full_path = os.path.join(os.getcwd(), target_directory, file_name)
        with open(full_path, "wb") as file_object:
            file_object.write(contents)
        pdfDataFetch = enpoint_to_ocr_rcrrakequota_annexure(full_path)
        dictData = {
            "date": datetime.datetime.strptime(pdfDataFetch.get("prog_id").split("/")[-2], "%b%Y").strftime("%b-%Y"),
            "coal_field": pdfDataFetch.get("booking_station"),
            "no_rake": pdfDataFetch.get("no_of_boxn").split(",")[0],
            "valid": pdfDataFetch.get("validity")
        }
        return dictData
    except Exception as e:
        success = False
        error_handler(e)
        
@router.post("/update/rakequotaannexure", tags=["Rcr Rake"])
def endpoint_to_update_annexure_rakequota_db(response: Response, data: rakequoataAnnexure):
    try:
        mPayload = data.dict()
        try:
            fetchRcrRakeQuotaData = rcrrakeQuota.objects.get(month=mPayload.get("month"), source_type=mPayload.get("source_type"))
            if fetchRcrRakeQuotaData:
                fetchRcrRakeQuotaData.update(
                    year=mPayload.get("year"),
                    coal_field=mPayload.get("coal_field"),
                    rake_alloted=mPayload.get("rake_alloted"),
                    valid_upto=mPayload.get("validity")
                )
        except DoesNotExist as e:
            rcrrakeQuota(
                month=mPayload.get("month"), 
                source_type=mPayload.get("source_type"),
                year=mPayload.get("year"),
                coal_field=mPayload.get("coal_field"),
                rake_alloted=mPayload.get("rake_alloted"),
                valid_upto=mPayload.get("validity")
            ).save()
        return {"details": "success"}
    except Exception as e:
        success = False
        error_handler(e)

